      SUBROUTINE USEC---- SET BEAM LINE TO BE USEDC-------------------------------------------------------------------      INCLUDE 'IOFLAG.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCHAR.CIN'C-------------------------------------------------------------------CC---- COMMA?C      CALL RDNEXT      IF (ENDFIL) GO TO 800      IF (ITEM .EQ. COMMA) THEN        CALL RDNEXT        IF (ENDFIL) GO TO 800      ENDIFCC---- BEAM LINE REFERENCEC      CALL DECUSE(ERROR)      IF (ENDFIL .OR. ERROR) GO TO 800      GO TO 900CC---- ERROR EXIT --- CLEAR LINE DATAC  800 ERROR = .TRUE.  900 RETURN      END